import { isDeepStrictEqual } from 'node:util';
// Diagnostic copy only: preserve deep strict equality without an unbounded byte diff.
function boundedBytesEqual(actual, expected, message) {
  if (isDeepStrictEqual(actual, expected)) return;
  const label = (value) => {
    if (value instanceof Uint8Array)
      return value.constructor.name + '(' + value.byteLength + ' bytes, sha256=' +
        createHash('sha256').update(value).digest('hex') + ')';
    if (value === null) return 'null';
    if (value === undefined) return 'undefined';
    return typeof value;
  };
  assert.ok(false, (message ?? 'Deep strict byte mismatch.') +
    ' Actual: ' + label(actual) + '; expected: ' + label(expected) + '.');
}

