// Diagnostic copy only: identical strict-identity truth with bounded mismatch labels.
function boundedIdentity(actual, expected, message) {
  if (Object.is(actual, expected)) return;
  const label = (value) => {
    if (value === null) return 'null';
    if (value === undefined) return 'undefined';
    if (typeof value !== 'object' && typeof value !== 'function') return String(value).slice(0, 80);
    return [value.tagName, value.id].filter((part) => typeof part === 'string')
      .map((part) => part.slice(0, 80)).join('#') || typeof value;
  };
  assert.ok(false, (message ?? 'Strict identity mismatch.') +
    ' Actual: ' + label(actual) + '; expected: ' + label(expected) + '.');
}

